/// <reference path="../../../env.d.ts" />

/**
 * Env for the events side (apps/server, packages/db), read from `process.env`.
 *
 * Nothing is validated here. The rules (required, URL shapes, defaults) live in
 * the repo-root `.env.schema`, and varlock enforces them where a process starts:
 * every package script runs through `varlock run`, which validates and injects
 * before any code loads. `process.env` is typed from the same schema
 * (`env.d.ts`, generated by varlock).
 *
 * Read once at import, as before. Empty strings count as unset.
 */
const read = (value: string | undefined) => (value === "" ? undefined : value);

export const env = {
	DATABASE_URL: process.env.DATABASE_URL,
	TURSO_AUTH_TOKEN: read(process.env.TURSO_AUTH_TOKEN),
	CORS_ORIGIN: process.env.CORS_ORIGIN,
	NODE_ENV: read(process.env.NODE_ENV) ?? "development",
};
